def test_return_tuple(run, x):
    result = run(x)
    assert isinstance(result, tuple) and len(result) == 2


def test_dataframe_shape(run, x):
    data, ax = run(x)
    assert data.shape == (5, 2)


def test_columns(run, x):
    data, ax = run(x)
    assert list(data.columns) == ['Category', 'Sales']


def test_category_order(run, x):
    data, ax = run(x)
    assert data['Category'].tolist() == ['Electronics', 'Fashion', 'Home & Kitchen', 'Automotive', 'Sports']


def test_numeric_sales(run, x):
    import pandas as pd
    data, ax = run(x)
    assert pd.api.types.is_numeric_dtype(data['Sales'])


def test_title(run, x):
    data, ax = run(x)
    assert ax.get_title() == 'Category-wise Sales Data'


def test_bar_count(run, x):
    data, ax = run(x)
    assert len(ax.patches) == 5


def test_bar_values(run, x):
    data, ax = run(x)
    assert [patch.get_height() for patch in ax.patches] == data['Sales'].tolist()


def test_appends_12(run, x):
    before_length = len(x['my_list'])
    run(x)
    assert len(x['my_list']) == before_length + 1 and x['my_list'][-1] == 12


def test_documented_seed_example(run, x):
    original = list(x['my_list'])
    data, ax = run(x)
    if original == [1, 2, 3] and x['seed'] == 123:
        assert data.to_dict('list') == {'Category': ['Electronics', 'Fashion', 'Home & Kitchen', 'Automotive', 'Sports'], 'Sales': [1395, 1266, 198, 351, 2472]}

